function sortedSquares(nums) {
  const result = new Array(nums.length);
  let left = 0;
  let right = nums.length - 1;
  let p = nums.length - 1;
  while (left <= right) {
    const leftSq = nums[left] * nums[left];
    const rightSq = nums[right] * nums[right];
    if (leftSq > rightSq) {
      result[p] = leftSq;
      left++;
    } else {
      result[p] = rightSq;
      right--;
    }
    p--;
  }
  return result;
}

